'use client';

import type { HTMLAttributes, JSX, Ref } from 'react';
import styles from './card.module.css';

const cx = (...c: Array<string | false | null | undefined>) => c.filter(Boolean).join(' ');

export interface CardProps extends HTMLAttributes<HTMLDivElement> {
  /** `default` = raised surface with border and shadow, `outline` = border only, `ghost` = no chrome. */
  variant?: 'default' | 'outline' | 'ghost';
  ref?: Ref<HTMLDivElement>;
}

/** A surface that groups related content and actions. Compose with CardHeader, CardContent and CardFooter. */
export function Card({ variant = 'default', className, ...rest }: CardProps): JSX.Element {
  return <div {...rest} data-variant={variant} className={cx(styles.card, className)} />;
}

export interface CardHeaderProps extends HTMLAttributes<HTMLDivElement> {
  /** Draws a hairline under the header. */
  divider?: boolean;
  ref?: Ref<HTMLDivElement>;
}

/** Title, description and an optional CardAction at the inline end. */
export function CardHeader({ divider = false, className, ...rest }: CardHeaderProps): JSX.Element {
  return <div {...rest} data-divider={divider || undefined} className={cx(styles.header, className)} />;
}

export interface CardTitleProps extends HTMLAttributes<HTMLHeadingElement> {
  /** Heading level. Pick the one that fits the page outline. */
  level?: 1 | 2 | 3 | 4 | 5 | 6;
  ref?: Ref<HTMLHeadingElement>;
}

export function CardTitle({ level = 3, className, ...rest }: CardTitleProps): JSX.Element {
  const Heading = `h${level}` as const;
  return <Heading {...rest} className={cx(styles.title, className)} />;
}

export interface CardDescriptionProps extends HTMLAttributes<HTMLParagraphElement> {
  ref?: Ref<HTMLParagraphElement>;
}

export function CardDescription({ className, ...rest }: CardDescriptionProps): JSX.Element {
  return <p {...rest} className={cx(styles.description, className)} />;
}

export interface CardActionProps extends HTMLAttributes<HTMLDivElement> {
  ref?: Ref<HTMLDivElement>;
}

/** Sits at the top inline-end corner of CardHeader, e.g. a menu button or a link. */
export function CardAction({ className, ...rest }: CardActionProps): JSX.Element {
  return <div {...rest} className={cx(styles.action, className)} />;
}

export interface CardContentProps extends HTMLAttributes<HTMLDivElement> {
  ref?: Ref<HTMLDivElement>;
}

export function CardContent({ className, ...rest }: CardContentProps): JSX.Element {
  return <div {...rest} className={cx(styles.content, className)} />;
}

export interface CardFooterProps extends HTMLAttributes<HTMLDivElement> {
  /** Draws a hairline above the footer. */
  divider?: boolean;
  ref?: Ref<HTMLDivElement>;
}

export function CardFooter({ divider = false, className, ...rest }: CardFooterProps): JSX.Element {
  return <div {...rest} data-divider={divider || undefined} className={cx(styles.footer, className)} />;
}

/*
 * Card — the card owns the block rhythm (padding-block + gap = card inset), each part owns its
 * inline padding. So parts can be omitted or reordered and spacing stays even; a part that needs to
 * bleed (a table, an image) simply sets padding-inline: 0.
 */

.card {
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: var(--strata-card-inset);
  min-inline-size: 0;
  padding-block: var(--strata-card-inset);
  border: 1px solid var(--strata-color-border-default);
  border-radius: var(--strata-radius-container);
  background-color: var(--strata-color-surface-raised);
  box-shadow: var(--strata-shadow-raised);
  color: var(--strata-color-text-default);
  font-family: var(--strata-font-body);
  font-size: var(--strata-font-size-md);
  line-height: var(--strata-line-height-normal);
  text-align: start;
}

.card[data-variant='outline'] {
  box-shadow: none;
}

.card[data-variant='ghost'] {
  border-color: transparent;
  background-color: transparent;
  box-shadow: none;
}

/* ---- header ------------------------------------------------------------ */

.header {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-auto-rows: min-content;
  align-items: start;
  row-gap: calc(var(--strata-space-1) * 1.5);
  column-gap: var(--strata-space-4);
  padding-inline: var(--strata-card-inset);
}

.header:has(> .action) {
  grid-template-columns: minmax(0, 1fr) auto;
}

.header[data-divider] {
  padding-block-end: var(--strata-card-inset);
  border-block-end: 1px solid var(--strata-color-border-subtle);
}

.title {
  margin: 0;
  color: var(--strata-color-text-default);
  font-family: var(--strata-font-heading);
  font-size: var(--strata-font-size-lg);
  font-weight: var(--strata-font-weight-semibold);
  /* Heading tracking is tuned for display sizes; at lg (16px) and below it closes up word spaces. */
  letter-spacing: 0;
  line-height: var(--strata-line-height-tight);
  text-wrap: balance;
}

.description {
  margin: 0;
  color: var(--strata-color-text-subtle);
  font-size: var(--strata-font-size-sm);
  line-height: var(--strata-line-height-normal);
  text-wrap: pretty;
}

.action {
  display: flex;
  grid-row: 1 / span 2;
  grid-column: 2;
  align-items: center;
  align-self: start;
  justify-self: end;
  gap: var(--strata-space-2);
}

/* ---- content & footer -------------------------------------------------- */

.content {
  min-inline-size: 0;
  padding-inline: var(--strata-card-inset);
}

.footer {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--strata-space-2);
  padding-inline: var(--strata-card-inset);
}

.footer[data-divider] {
  padding-block-start: var(--strata-card-inset);
  border-block-start: 1px solid var(--strata-color-border-subtle);
}
